{"command": "cat > /workspace/main.go <<'GOEOF'
package main

import (
	"embed"
	"fmt"
	"os"
	"strings"
	"time"
)

//go:embed helptxt/*.txt
var helpFS embed.FS

const versionString = "skeema version 1.13.2-community, commit 9a541d7, released 2026-08-10T23:10:35Z\n"

var validCommands = []string{"add-environment", "diff", "format", "help", "init", "lint", "pull", "push", "version"}

func isValidCommand(s string) bool {
	for _, c := range validCommands {
		if c == s {
			return true
		}
	}
	return false
}

func getHelpText(cmd string) string {
	var fname string
	if cmd == "" {
		fname = "helptxt/main.txt"
	} else if cmd == "add-environment" {
		fname = "helptxt/add-environment.txt"
	} else {
		fname = "helptxt/" + cmd + ".txt"
	}
	data, err := helpFS.ReadFile(fname)
	if err != nil {
		return ""
	}
	return string(data)
}

func logMsg(level, msg string) {
	ts := time.Now().Format("2006-01-02 15:04:05")
	extra := ""
	if level == "INFO" || level == "WARN" {
		extra = " "
	}
	fmt.Fprintf(os.Stderr, "%s [%s]%s %s\n", ts, level, extra, msg)
	// Note: format is timestamp + space + [LEVEL] + (extra space for INFO/WARN) + space + msg
	// For INFO/WARN, extra=" " gives two spaces total after ]; for others, one space.
}

func logError(msg string) {
	logMsg("ERROR", msg)
}
func logWarn(msg string) {
	logMsg("WARN", msg)
}
func logInfo(msg string) {
	logMsg("INFO", msg)
}
func logDebug(msg string) {
	logMsg("DEBUG", msg)
}

func main() {
	os.Exit(run())
}
GOEOF
cat /workspace/main.go"}

