type parsedState struct {
	command       string
	commandIdx  int // index in args where command found, -1 if none
	positionals []string // all positionals (excluding command? includes environment etc.)
	// options
	globalOpts map[string]string // long name -> value (for bools, "true"/"false" string? store raw)
	cmdOpts    map[string]string
	// flags
	helpPresent bool
	helpValue   *string // value via = or attached, nil if bare
	helpIsShort bool
	versionPresent bool
	versionValue   *string // raw value if via =, nil if bare
	versionIsGlobal bool // whether version flag was before command? Actually version can be anywhere
	debugValue *string // nil if not present? store raw? For bare, true
	debugPresent bool
	// password bare?
	passwordBareGlobal bool
	passwordBareCmd    bool
	passwordValueGlobal *string
	passwordValueCmd    *string
	// my-cnf present?
	myCnfPresent bool
	// for error reporting
}

func run() int {
	args := os.Args[1:]
	return runWithArgs(args)
}

func runWithArgs(args []string) int {
	// First, quick parse to handle CLI errors, help, version, etc.
	// We need to parse options and detect unknown/missing before other logic.
	state, errCode, errMsg := parseArgs(args)
	if errCode != 0 {
		// errMsg already includes timestamp? No, we need to log it
		if errMsg != "" {
			// errMsg is like `CLI: Unknown option "bogus"` without timestamp?
			// Actually we should log via logError
			// But some errors are like `Enter password: ` + errors? Those are special.
			// For now, parseArgs returns error message to be logged as ERROR (with timestamp)
			// except for password prompt which includes `Enter password: \n` prefix
			if strings.HasPrefix(errMsg, "Enter password: ") {
				fmt.Fprintf(os.Stderr, "Enter password: \n")
				rest := strings.TrimPrefix(errMsg, "Enter password: ")
				// rest may contain multiple lines separated by \n?
				for _, line := range strings.Split(rest, "\n") {
					if line == "" {
						continue
					}
					logError(line)
				}
			} else {
				logError(errMsg)
			}
		}
		// For debug exit code? CLI errors do NOT show debug exit line (as observed)
		// So just return errCode
		return errCode
	}
	// state parsed successfully, now handle help/version/debug logic
	// Check debug flag to determine if debug enabled
	debugEnabled := false
	if state.debugPresent {
		// state.debugValue holds raw? For bare, true. For =value, parse bool
		if state.debugValue == nil {
			debugEnabled = true
		} else {
			debugEnabled = parseBoolValue(*state.debugValue)
		}
	}
	// Check my-cnf deprecation warning? Need to emit before other logic? It appears for version/help as well.
	// Actually my-cnf warning appears even for version/help? Yes, --my-cnf version gave warning.
	// So emit it early if present, before help/version? Order: warning then help/version output?
	// For --my-cnf --debug version, output was warning then debug exit line. So warning first.
	// For --my-cnf version (no debug), output was version string to stdout, warning to stderr. Order doesn't matter much.
	// We'll collect warnings to emit.
	var warnings []string
	if state.myCnfPresent {
		warnings = append(warnings, `Option --my-cnf is deprecated. This option will be removed in Skeema v2, and .my.cnf will always be parsed, with additional safety logic already in place. For more information, visit https://www.skeema.io/v2-changes`)
