func doFormat(state *parsedState, debugEnabled bool, env string) int {
	cwd, _ := os.Getwd()
	allDirs := findAllDirs(cwd)
	for _, d := range allDirs {
		fpath := filepath.Join(d, ".skeema")
		if _, err := os.Stat(fpath); err != nil {
			continue
		}
		if _, err := parseSkeemaFile(fpath); err != nil {
			logError(err.Error())
			if debugEnabled {
				logDebug("Exit code 78")
			}
			return 78
		}
	}
	writeEnabled := true
	if v, ok := state.globalOpts["write"]; ok {
		writeEnabled = parseBoolValue(v)
	}
	if v, ok := state.cmdOpts["write"]; ok {
		writeEnabled = parseBoolValue(v)
	}
	if _, ok := state.globalOpts["skip-write"]; ok {
		writeEnabled = false
	}
	if _, ok := state.cmdOpts["skip-write"]; ok {
		writeEnabled = false
	}
	failed := false
	for _, dir := range allDirs {
		if writeEnabled {
			logInfo(fmt.Sprintf("Reformatting %s", dir))
		} else {
			logInfo(fmt.Sprintf("Checking format of %s", dir))
		}
		fpath := filepath.Join(dir, ".skeema")
		if _, err := os.Stat(fpath); err != nil {
			continue
		}
		merged, _, err := getMergedConfig(dir, env, state.globalOpts, state.cmdOpts)
		if err != nil {
			logError(err.Error())
			if debugEnabled {
				logDebug("Exit code 78")
			}
			return 78
		}
		schema, hasSchema := merged["schema"]
		if !hasSchema || schema == "" {
			continue
		}
		cfg := merged
		if err := checkIgnoreRegex(cfg); err != nil {
			logError(fmt.Sprintf("Skipping %s: %s", dir, err.Error()))
			failed = true
			continue
		}
		if err := checkSSLMode(cfg); err != nil {
			logError(fmt.Sprintf("Skipping %s: %s", dir, err.Error()))
			failed = true
			continue
		}
		if err := checkConnectOptions(cfg); err != nil {
